class Solution:
    def maxScore(self, n, k, x, arr):
        S = []

        # Compute sum of medians for each subarray size
        for L in range(1, n + 1):
            total = 0
            for i in range(n - L + 1):
                window = sorted(arr[i:i+L])
                total += window[(L - 1) // 2]
            S.append(total)

        res = 0

        # Greedy bitwise construction
        for bit in range(31, -1, -1):
            candidate = res | (1 << bit)
            count = 0

            for val in S:
                if (val & candidate) == candidate:
                    count += 1

            if count >= k:
                res = candidate

        return x | res
